def unwrap(r):
    d=r.get('data') or {}
    return d.get('data',d) if isinstance(d,dict) else {}

def iter_rows(run,database_id,flt=None):
    cur=None
    while True:
        a={'database_id':database_id,'page_size':100,'filter':flt or {}}
        if cur: a['start_cursor']=cur
        resp,err=run('NOTION_QUERY_DATABASE_WITH_FILTER',a)
        if err: raise RuntimeError(err)
        data=unwrap(resp)
        for x in data.get('results',[]):
            yield x
        if not data.get('has_more'): break
        cur=data.get('next_cursor')
